// Explorer portraits: 40x40 pixel busts in a neon-blue palette, drawn from the avatar numbers.
// Everything is original art generated by code (shapes + shading + outline), nothing is an image file.
// The same numbers are saved by the server (AVATAR_LIMITS must match server/src/game/rules.js).
export const INK = '#050b26';
export const CHAR_W = 40, CHAR_H = 40;
const N = 40;

export const AVATAR_LIMITS = { body: 5, skin: 6, hairStyle: 8, hairColor: 8, outfit: 4, outfitColor: 8, accessory: 6, eyewear: 5, headgear: 5, mood: 3, bg: 6 };
export const DEFAULT_AVATAR = { body: 0, skin: 1, hairStyle: 0, hairColor: 0, outfit: 0, outfitColor: 0, accessory: 0, eyewear: 0, headgear: 0, mood: 0, bg: 0 };

export const BODIES = ['Man', 'Woman', 'Android', 'Alien', 'Bear'];
// Skin / material tones: [highlight, base, shadow]. All cool, so every character fits the neon-blue world.
export const TONES = [
  ['#e4f8ff', '#a6dcf7', '#5fa6d8'], ['#9ff2ff', '#3fd8f5', '#1c8fc4'], ['#9cc4ff', '#5b93ff', '#2f5bd0'],
  ['#c9d5ee', '#8a9dc9', '#51649a'], ['#a9a6ff', '#6f6cf0', '#3f3cb0'], ['#5f94d0', '#3a6aa8', '#1f4170'],
];
export const SKIN = TONES.map((t) => t[1]);
export const HAIR = ['#141a4a', '#2a3fa8', '#2de2ff', '#f2f8ff', '#4a86ff', '#22d3b8', '#8a78ff', '#aab8d8'];
export const OUTFIT = ['#2f6bff', '#1a2f8f', '#2de2ff', '#e9f3ff', '#5b4bd6', '#0f7f9f', '#8aa4d8', '#0b1540'];
export const BG = ['#123a8c', '#1f66d6', '#0b6f8f', '#2b2f9a', '#17496b', '#3a8fe0'];
export const HAIR_STYLES = ['Crop', 'Mohawk', 'Long', 'Bob', 'Topknot', 'Slick', 'Curly', 'Shaved'];
export const OUTFITS = ['Jacket', 'Hoodie', 'Tech suit', 'Turtleneck'];
export const GEAR = ['None', 'Headphones', 'Earring', 'Antenna', 'Face mask', 'Cyber implant'];
export const EYEWEAR = ['None', 'Shades', 'Round specs', 'Visor', 'Goggles'];
export const HEADGEAR = ['None', 'Cap', 'Beanie', 'Headband', 'Hood'];
export const MOODS = ['Calm', 'Smirk', 'Stern'];
export const HUMAN = (a) => a.body <= 1;

// A cast of ready-made characters to start from (all still editable).
export const PRESETS = [
  { name: 'Kai', a: { body: 0, skin: 1, hairStyle: 0, hairColor: 0, outfit: 0, outfitColor: 0, accessory: 0, eyewear: 0, headgear: 0, mood: 0, bg: 0 } },
  { name: 'Nova', a: { body: 1, skin: 0, hairStyle: 2, hairColor: 2, outfit: 1, outfitColor: 3, accessory: 2, eyewear: 0, headgear: 0, mood: 1, bg: 1 } },
  { name: 'Vex', a: { body: 0, skin: 5, hairStyle: 1, hairColor: 2, outfit: 2, outfitColor: 2, accessory: 0, eyewear: 1, headgear: 0, mood: 2, bg: 3 } },
  { name: 'Echo', a: { body: 1, skin: 3, hairStyle: 4, hairColor: 1, outfit: 3, outfitColor: 6, accessory: 5, eyewear: 2, headgear: 0, mood: 0, bg: 2 } },
  { name: 'Unit-7', a: { body: 2, skin: 3, hairStyle: 0, hairColor: 0, outfit: 2, outfitColor: 7, accessory: 3, eyewear: 0, headgear: 0, mood: 0, bg: 4 } },
  { name: 'Zorp', a: { body: 3, skin: 1, hairStyle: 0, hairColor: 0, outfit: 0, outfitColor: 1, accessory: 0, eyewear: 0, headgear: 0, mood: 1, bg: 5 } },
  { name: 'Bruno', a: { body: 4, skin: 2, hairStyle: 0, hairColor: 0, outfit: 1, outfitColor: 0, accessory: 0, eyewear: 0, headgear: 1, mood: 0, bg: 0 } },
  { name: 'Rhea', a: { body: 0, skin: 4, hairStyle: 5, hairColor: 4, outfit: 0, outfitColor: 4, accessory: 1, eyewear: 3, headgear: 0, mood: 1, bg: 1 } },
  { name: 'Mira', a: { body: 1, skin: 2, hairStyle: 3, hairColor: 6, outfit: 0, outfitColor: 5, accessory: 0, eyewear: 4, headgear: 0, mood: 2, bg: 3 } },
  { name: 'Dax', a: { body: 0, skin: 0, hairStyle: 6, hairColor: 1, outfit: 1, outfitColor: 2, accessory: 4, eyewear: 0, headgear: 3, mood: 0, bg: 2 } },
  { name: 'Lux', a: { body: 1, skin: 5, hairStyle: 7, hairColor: 7, outfit: 2, outfitColor: 0, accessory: 0, eyewear: 2, headgear: 2, mood: 1, bg: 4 } },
  { name: 'Shade', a: { body: 0, skin: 3, hairStyle: 2, hairColor: 5, outfit: 3, outfitColor: 1, accessory: 0, eyewear: 0, headgear: 4, mood: 2, bg: 5 } },
];

export function normalizeAvatar(raw) {
  const src = raw && typeof raw === 'object' ? raw : {};
  const out = {};
  for (const [k, max] of Object.entries(AVATAR_LIMITS)) {
    const v = Number(src[k]);
    out[k] = Number.isInteger(v) && v >= 0 && v < max ? v : DEFAULT_AVATAR[k];
  }
  return out;
}

export function randomAvatar() {
  const r = (n) => Math.floor(Math.random() * n);
  const body = Math.random() < 0.7 ? r(2) : 2 + r(3);
  return {
    body, skin: r(6), hairStyle: r(8), hairColor: r(8), outfit: r(4), outfitColor: r(8),
    accessory: Math.random() < 0.5 ? 0 : 1 + r(5), eyewear: Math.random() < 0.5 ? 0 : 1 + r(4),
    headgear: Math.random() < 0.6 ? 0 : 1 + r(4), mood: r(3), bg: r(6),
  };
}

// ---------- colour + grid helpers ----------
function mix(hex, to, f) {
  const a = parseInt(hex.slice(1), 16), b = parseInt(to.slice(1), 16);
  const ch = (s) => Math.round(((a >> s) & 255) * (1 - f) + ((b >> s) & 255) * f);
  return `#${((1 << 24) | (ch(16) << 16) | (ch(8) << 8) | ch(0)).toString(16).slice(1)}`;
}
const lit = (h, f = 0.35) => mix(h, '#ffffff', f);
const dim = (h, f = 0.35) => mix(h, '#000a30', f);

function makeGrid() { return Array.from({ length: N }, () => Array(N).fill(null)); }
function outlineGrid(g) {
  const out = g.map((r) => r.slice());
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
    if (g[y][x]) continue;
    if ((y > 0 && g[y - 1][x]) || (y < N - 1 && g[y + 1][x]) || (x > 0 && g[y][x - 1]) || (x < N - 1 && g[y][x + 1])) out[y][x] = INK;
  }
  return out;
}

export function drawPortrait(raw) {
  const a = normalizeAvatar(raw);
  const g = makeGrid();
  const mask = makeGrid(); // where the face skin is, for shading
  const put = (x, y, c) => { if (x >= 0 && x < N && y >= 0 && y < N) g[y][x] = c; };
  const rect = (x, y, w, h, c) => { for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) put(x + i, y + j, c); };
  const ell = (cx, cy, rx, ry, c, keep) => {
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
      const dx = (x - cx) / rx, dy = (y - cy) / ry;
      if (dx * dx + dy * dy <= 1 && (!keep || keep(x, y))) put(x, y, c);
    }
  };
  const ring = (cx, cy, rx, ry, rx2, ry2, c, keep) => {
    for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) {
      const d1 = ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2, d2 = ((x - cx) / rx2) ** 2 + ((y - cy) / ry2) ** 2;
      if (d1 <= 1 && d2 > 1 && (!keep || keep(x, y))) put(x, y, c);
    }
  };

  const [tHi, tMid, tLo] = TONES[a.skin];
  const hair = HAIR[a.hairColor], hairHi = lit(hair, 0.4), hairLo = dim(hair, 0.4);
  const oc = OUTFIT[a.outfitColor], ocHi = lit(oc, 0.35), ocLo = dim(oc, 0.4);
  const human = HUMAN(a);
  const woman = a.body === 1;
  const CX = 20;
  const GLOW = '#2de2ff', WHITE = '#f2f8ff', NAVY = '#0a1450';

  // ----- 1. things behind the head: long hair, hood, afro, bear ears -----
  if (human && a.headgear !== 4) {
    if (a.hairStyle === 2) { rect(10, 9, 21, 28, hair); rect(10, 28, 21, 9, hairLo); }
    if (a.hairStyle === 3) rect(10, 10, 21, 17, hair);
    if (a.hairStyle === 6) ell(CX, 12, 13, 11, hair);
    if (a.hairStyle === 4) { ell(CX, 3.5, 4, 3.4, hair); rect(CX - 1, 6, 3, 4, hair); }
  }
  if (a.headgear === 4) ell(CX, 17, 12.5, 14.5, ocLo);
  if (a.body === 4) { ell(11, 9, 4, 4, tMid); ell(29, 9, 4, 4, tMid); ell(11, 9, 2, 2, tLo); ell(29, 9, 2, 2, tLo); }

  // ----- 2. neck and shoulders / outfit -----
  const neckW = a.body === 3 ? 5 : woman ? 7 : 9;
  rect(CX - (neckW >> 1), 26, neckW, 7, tMid);
  rect(CX - (neckW >> 1), 26, neckW, 3, tLo);
  if (a.body === 2) for (let y = 27; y < 32; y += 2) rect(CX - 4, y, 9, 1, dim(tMid, 0.5));
  for (let y = 31; y < N; y++) {
    const half = Math.min(20, (woman ? 7 : 8) + Math.round((y - 30) * (woman ? 2.2 : 2.6)));
    for (let x = CX - half; x <= CX + half; x++) put(x, y, x > CX + half * 0.35 ? ocLo : x < CX - half * 0.55 ? ocHi : oc);
  }
  rect(0, 39, 40, 1, ocLo);
  const shirt = a.outfitColor === 3 ? '#9fb4e0' : lit(oc, 0.7);
  if (a.outfit === 0) { // jacket: open V collar, zip
    for (let y = 31; y < 37; y++) { const w = 5 - (y - 31); rect(CX - w, y, w * 2 + 1, 1, y < 33 ? tMid : shirt); }
    for (let y = 31; y < 36; y++) { put(CX - (6 - (y - 31)), y, ocHi); put(CX + (6 - (y - 31)), y, ocLo); }
    rect(CX, 36, 1, 4, dim(oc, 0.6)); rect(CX - 1, 37, 3, 1, GLOW);
  } else if (a.outfit === 1) { // hoodie: hood bunched at the neck + drawstrings
    ring(CX, 31, 9, 4, 6, 2.2, ocHi, (x, y) => y >= 29);
    rect(CX - 6, 31, 2, 1, ocLo); rect(CX + 5, 31, 2, 1, ocLo);
    rect(CX - 4, 33, 1, 5, WHITE); rect(CX + 4, 33, 1, 5, WHITE); put(CX - 4, 38, GLOW); put(CX + 4, 38, GLOW);
    rect(CX - 8, 36, 17, 1, ocLo);
  } else if (a.outfit === 2) { // tech suit: high collar + glow lines
    rect(CX - 8, 28, 17, 4, dim(oc, 0.45)); rect(CX - 8, 28, 17, 1, GLOW);
    rect(CX - 1, 29, 3, 3, GLOW);
    for (let i = 0; i < 4; i++) { put(CX - 10 - i, 35 + (i >> 1), GLOW); put(CX + 10 + i, 35 + (i >> 1), GLOW); }
    rect(CX - 8, 36, 5, 1, dim(oc, 0.6)); rect(CX + 4, 36, 5, 1, dim(oc, 0.6));
  } else { // turtleneck
    rect(CX - 6, 27, 13, 6, oc); for (let y = 27; y < 33; y += 2) rect(CX - 6, y, 13, 1, ocLo);
    rect(CX - 6, 27, 2, 6, ocHi); rect(CX + 4, 27, 3, 6, ocLo);
  }

  // ----- 3. the head -----
  const faceTop = 7;
  if (a.body === 0) { // man: strong square jaw
    ell(CX, 16, 9, 9, tMid);
    for (let y = 18; y <= 27; y++) { let x0 = 12, x1 = 28; if (y >= 26) { x0 += y - 25; x1 -= y - 25; } rect(x0, y, x1 - x0 + 1, 1, tMid); }
    rect(10, 17, 1, 4, tMid); rect(30, 17, 1, 4, tMid); put(10, 18, tLo); put(30, 18, tLo);
  } else if (woman) { // woman: tapered jaw
    ell(CX, 16, 8.4, 9, tMid);
    for (let y = 18; y <= 28; y++) { const half = Math.round(8 - (y - 18) * 0.5); rect(CX - half, y, half * 2 + 1, 1, tMid); }
    rect(11, 18, 1, 3, tMid); rect(29, 18, 1, 3, tMid); put(11, 19, tLo); put(29, 19, tLo);
  } else if (a.body === 2) { // android: plated rounded head
    rect(11, 7, 19, 21, tMid); for (const [x, y] of [[11, 7], [29, 7], [11, 27], [29, 27], [12, 7], [28, 7]]) put(x, y, null);
    rect(9, 15, 2, 7, tLo); rect(30, 15, 2, 7, tLo); put(9, 17, GLOW); put(31, 17, GLOW);
    rect(11, 11, 19, 1, tLo); rect(19, 4, 3, 3, dim(tMid, 0.3)); put(20, 3, GLOW); put(20, 2, WHITE);
  } else if (a.body === 3) { // alien: tall head, narrow chin
    ell(CX, 14, 10.5, 11.5, tMid); ell(CX, 23, 6.5, 6, tMid); rect(17, 28, 7, 1, tMid);
  } else { // bear: round head, muzzle
    ell(CX, 17, 10.5, 10, tMid); ell(CX, 22, 5.5, 4.2, lit(tMid, 0.45));
  }
  // mark face pixels for shading (everything painted in tone-mid right now at y 4..29)
  for (let y = 0; y < 30; y++) for (let x = 0; x < N; x++) if (g[y][x] === tMid) mask[y][x] = 1;

  // shading: light from the top-left, soft crescent of shadow bottom-right, highlight on forehead
  for (let y = 0; y < 30; y++) for (let x = 0; x < N; x++) {
    if (!mask[y][x]) continue;
    const dx = (x - (CX - 3)) / 11, dy = (y - 14) / 12, d = dx * dx + dy * dy;
    if (d > 0.82 && x >= CX) g[y][x] = tLo;
    else if (d < 0.1 && y < 16 && x < CX) g[y][x] = tHi;
  }
  // cheek light for humans
  if (human) { put(14, 21, tHi); put(14, 20, tHi); put(15, 22, tHi); }

  // ----- 4. face features -----
  const eyeL = 16, eyeR = 24, eyeY = 17;
  const hasVisor = a.eyewear === 3;
  if (human) {
    // eyes: lid line, white, dark pupil with a cyan spark
    for (const ex of [eyeL, eyeR]) {
      rect(ex - 1, eyeY - 1, 3, 1, dim(tMid, 0.65));
      rect(ex - 1, eyeY, 3, 1, WHITE);
      put(ex, eyeY, NAVY); put(ex + (ex < CX ? 1 : -1), eyeY, GLOW);
      if (woman) { put(ex - 2, eyeY - 1, INK); put(ex + 2, eyeY - 1, INK); }
    }
    // brows
    const bc = a.hairStyle === 7 ? dim(tMid, 0.55) : hairLo;
    const stern = a.mood === 2;
    rect(eyeL - 2, eyeY - 3, 4, 1, bc); rect(eyeR - 1, eyeY - 3, 4, 1, bc);
    if (stern) { put(eyeL + 1, eyeY - 2, bc); put(eyeR - 1, eyeY - 2, bc); }
    // nose
    put(CX + 1, 20, tLo); put(CX, 21, tLo); put(CX + 1, 21, tLo); put(CX - 1, 22, dim(tMid, 0.25));
    // mouth
    const lip = woman ? '#3f7dff' : dim(tMid, 0.7);
    if (a.mood === 0) { rect(CX - 2, 24, 5, 1, lip); if (woman) rect(CX - 1, 25, 3, 1, lit('#3f7dff', 0.3)); }
    if (a.mood === 1) { rect(CX - 2, 24, 4, 1, lip); put(CX + 2, 23, lip); put(CX + 3, 22, lip); if (woman) rect(CX - 1, 25, 3, 1, lit('#3f7dff', 0.3)); }
    if (a.mood === 2) { rect(CX - 2, 24, 5, 1, lip); put(CX - 3, 25, lip); put(CX + 3, 25, lip); }
  } else if (a.body === 2) { // android: dark visor with glowing eyes + grille mouth
    rect(13, 13, 15, 7, NAVY); rect(13, 13, 15, 1, '#16318a');
    rect(15, 15, 4, 3, GLOW); rect(23, 15, 4, 3, GLOW); rect(15, 15, 4, 1, WHITE); rect(23, 15, 4, 1, WHITE);
    if (a.mood === 1) { rect(15, 17, 1, 1, NAVY); rect(26, 17, 1, 1, NAVY); }
    if (a.mood === 2) { rect(15, 15, 2, 1, NAVY); rect(25, 15, 2, 1, NAVY); }
    rect(16, 23, 9, 3, NAVY); for (let x = 17; x < 25; x += 2) rect(x, 23, 1, 3, a.mood === 2 ? '#ff5fa2' : GLOW);
  } else if (a.body === 3) { // alien: huge almond eyes
    for (const [ex, dir] of [[14.5, -1], [26.5, 1]]) {
      ell(ex, 17, 4.3, 3.3, NAVY, (x, y) => (dir < 0 ? x + (y - 17) * -0.5 : x + (y - 17) * 0.5) > -99);
      put(Math.round(ex - 2), 16, GLOW); put(Math.round(ex - 1), 16, WHITE); put(Math.round(ex + 2), 18, GLOW);
    }
    put(19, 21, tLo); put(22, 21, tLo);
    if (a.mood === 0) rect(18, 25, 5, 1, dim(tMid, 0.6));
    if (a.mood === 1) { rect(18, 25, 4, 1, dim(tMid, 0.6)); put(22, 24, dim(tMid, 0.6)); }
    if (a.mood === 2) { rect(18, 25, 5, 1, dim(tMid, 0.6)); put(17, 26, dim(tMid, 0.6)); put(23, 26, dim(tMid, 0.6)); }
    put(CX, 8, tHi); put(CX, 9, tHi);
  } else { // bear
    rect(15, 15, 2, 2, NAVY); rect(24, 15, 2, 2, NAVY); put(15, 15, WHITE); put(24, 15, WHITE);
    rect(19, 19, 3, 2, INK); put(19, 19, '#5aa0ff');
    put(CX, 21, INK); put(CX, 22, dim(tMid, 0.5));
    if (a.mood === 0) { put(18, 23, dim(tMid, 0.6)); put(19, 24, dim(tMid, 0.6)); put(21, 24, dim(tMid, 0.6)); put(22, 23, dim(tMid, 0.6)); }
    if (a.mood === 1) { rect(18, 23, 5, 1, dim(tMid, 0.6)); put(23, 22, dim(tMid, 0.6)); }
    if (a.mood === 2) { rect(18, 24, 5, 1, dim(tMid, 0.6)); put(17, 25, dim(tMid, 0.6)); put(23, 25, dim(tMid, 0.6)); rect(14, 13, 3, 1, dim(tMid, 0.6)); rect(24, 13, 3, 1, dim(tMid, 0.6)); }
  }

  // ----- 5. hair on the front (humans only) -----
  if (human && a.headgear !== 4 || (human && a.headgear === 4)) {
    const front = (cond) => { for (let y = 3; y <= 18; y++) for (let x = 8; x <= 32; x++) if (cond(x, y)) { put(x, y, hair); if (mask[y]?.[x] === undefined) { /* keep */ } } };
    const cap = (x, y) => ((x - CX) / 10.5) ** 2 + ((y - 12) / 8) ** 2 <= 1 && y <= 12;
    switch (a.hairStyle) {
      case 0: front(cap); rect(11, 12, 1, 5, hair); rect(29, 12, 1, 5, hair); rect(12, 12, 4, 1, hair); rect(25, 12, 4, 1, hair); put(15, 13, hair); put(26, 13, hair); break;
      case 1: for (let y = 0; y <= 12; y++) { const hw = y < 3 ? 1 : y < 7 ? 2 : 3; rect(CX - hw, y, hw * 2 + 1, 1, hair); } put(CX - 2, 0, hairHi); rect(11, 10, 2, 3, hairLo); rect(28, 10, 2, 3, hairLo); put(12, 9, hair); put(29, 9, hair); break;
      case 2: front((x, y) => ((x - CX) / 10.5) ** 2 + ((y - 12) / 8) ** 2 <= 1 && y <= 12); rect(10, 12, 3, 22, hair); rect(28, 12, 3, 22, hair); rect(10, 12, 1, 22, hairHi); rect(30, 12, 1, 22, hairLo); for (let x = 13; x < 20; x++) put(x, 12 + ((x - 13) >> 1), hair); break;
      case 3: front(cap); rect(10, 11, 3, 15, hair); rect(28, 11, 3, 15, hair); rect(10, 25, 5, 1, hairLo); rect(26, 25, 5, 1, hairLo); rect(12, 12, 5, 2, hair); rect(24, 12, 5, 2, hair); break;
      case 4: front(cap); rect(11, 12, 1, 4, hair); rect(29, 12, 1, 4, hair); put(CX - 2, 2, hairHi); put(CX - 1, 2, hairHi); rect(CX - 3, 8, 7, 1, hairLo); break;
      case 5: front((x, y) => ((x - CX) / 11.5) ** 2 + ((y - 11) / 8.5) ** 2 <= 1 && y <= 12); rect(11, 12, 1, 5, hair); rect(29, 12, 1, 5, hair); for (let i = 0; i < 6; i++) put(CX - 6 + i * 2, 4 + (i >> 1), hairHi); for (let y = 6; y <= 11; y++) put(CX - 8 + (y - 6), y, hairLo); break;
      case 6: front((x, y) => ((x - CX) / 11) ** 2 + ((y - 11) / 8) ** 2 <= 1 && y <= 11); for (const [x, y] of [[15, 12], [17, 12], [24, 12], [26, 12], [11, 12], [29, 12]]) put(x, y, hair); for (let i = 0; i < 7; i++) put(11 + i * 3, 4 + ((i * 5) % 3), hairHi); break;
      default: front((x, y) => ((x - CX) / 10) ** 2 + ((y - 12) / 7.5) ** 2 <= 1 && y <= 11 && (x + y) % 2 === 0); rect(13, 10, 5, 1, hair); put(12, 11, hair); break;
    }
  }

  // ----- 6. headgear -----
  if (a.headgear === 1) { // cap
    ell(CX, 11, 10.5, 6.5, oc, (x, y) => y <= 11); rect(10, 11, 21, 2, ocLo);
    rect(18, 12, 15, 2, ocHi); rect(18, 13, 15, 1, ocLo); rect(CX - 1, 7, 3, 2, GLOW);
  } else if (a.headgear === 2) { // beanie
    ell(CX, 11, 10.8, 7.5, oc, (x, y) => y <= 11); rect(10, 10, 21, 4, ocHi);
    for (let x = 10; x < 31; x += 2) rect(x, 10, 1, 4, ocLo); put(CX, 2, GLOW);
  } else if (a.headgear === 3) { // tech headband
    rect(10, 10, 21, 3, dim(oc, 0.4)); rect(10, 11, 21, 1, GLOW); rect(CX - 2, 10, 5, 3, NAVY); put(CX, 11, WHITE);
  } else if (a.headgear === 4) { // hood front
    ring(CX, 17, 12.5, 14.5, 10.2, 12.2, oc, (x, y) => y <= 27); ring(CX, 17, 12.5, 14.5, 10.2, 12.2, ocHi, (x, y) => y <= 9 && x < CX);
    rect(11, 10, 1, 1, ocLo);
  }

  // ----- 7. eyewear -----
  if (a.eyewear === 1) {
    rect(13, 16, 6, 3, NAVY); rect(22, 16, 6, 3, NAVY); rect(19, 16, 3, 1, NAVY); rect(11, 16, 2, 1, NAVY); rect(28, 16, 3, 1, NAVY);
    put(14, 16, GLOW); put(15, 16, '#4a86ff'); put(23, 16, GLOW); put(24, 16, '#4a86ff');
  } else if (a.eyewear === 2) {
    ring(eyeL, eyeY, 3.8, 3.3, 2.3, 1.9, GLOW); ring(eyeR, eyeY, 3.8, 3.3, 2.3, 1.9, GLOW); rect(19, 16, 3, 1, GLOW);
    rect(11, 16, 1, 1, GLOW); rect(29, 16, 2, 1, GLOW);
  } else if (a.eyewear === 3 && human) {
    rect(12, 15, 17, 4, NAVY); rect(13, 16, 15, 2, GLOW); rect(13, 16, 15, 1, WHITE); put(12, 15, null); put(28, 15, null);
    for (let x = 14; x < 28; x += 4) put(x, 17, '#7ad8ff');
  } else if (a.eyewear === 4 && human) {
    ell(eyeL, eyeY, 3.6, 3.6, '#16318a'); ell(eyeR, eyeY, 3.6, 3.6, '#16318a');
    ell(eyeL, eyeY, 2.4, 2.4, GLOW); ell(eyeR, eyeY, 2.4, 2.4, GLOW); put(eyeL - 1, eyeY - 1, WHITE); put(eyeR - 1, eyeY - 1, WHITE);
    rect(11, 16, 2, 2, '#16318a'); rect(28, 16, 3, 2, '#16318a'); rect(19, 16, 3, 2, '#16318a');
  } else if (a.eyewear === 3 && !human) {
    rect(12, 15, 17, 4, NAVY); rect(13, 16, 15, 2, GLOW); rect(13, 16, 15, 1, WHITE);
  } else if (a.eyewear === 4 && !human) {
    ring(eyeL, eyeY, 4, 3.6, 2.6, 2.2, '#16318a'); ring(eyeR, eyeY, 4, 3.6, 2.6, 2.2, '#16318a'); rect(19, 16, 3, 1, '#16318a');
  } else if (a.eyewear === 1 && a.body >= 2) { // shades on non-humans already drawn above
  }

  // ----- 8. gear -----
  if (a.accessory === 1) { // headphones
    ring(CX, 13, 13.2, 12.5, 11.4, 10.8, '#1a2f8f', (x, y) => y <= 12); ring(CX, 13, 13.2, 12.5, 12.3, 11.7, GLOW, (x, y) => y <= 12);
    rect(7, 14, 4, 8, '#1a2f8f'); rect(30, 14, 4, 8, '#1a2f8f'); rect(8, 15, 2, 6, GLOW); rect(31, 15, 2, 6, GLOW); put(8, 15, WHITE); put(31, 15, WHITE);
  } else if (a.accessory === 2) { // earring + stud
    rect(9, 20, 1, 3, GLOW); put(9, 23, WHITE); put(31, 19, GLOW);
  } else if (a.accessory === 3) { // antenna
    rect(28, 3, 1, 6, tLo); rect(27, 0, 3, 3, GLOW); put(28, 0, WHITE);
  } else if (a.accessory === 4) { // tech face mask
    for (let y = 22; y <= 29; y++) for (let x = 0; x < N; x++) if (mask[y][x]) g[y][x] = y === 22 ? GLOW : y % 2 ? '#16318a' : NAVY;
    for (let x = 16; x < 25; x += 2) for (let y = 24; y <= 27; y += 2) if (g[y][x] && mask[y][x]) g[y][x] = '#2f6bff';
    rect(11, 20, 2, 3, NAVY); rect(28, 20, 2, 3, NAVY);
  } else if (a.accessory === 5) { // cyber implant: glowing circuit on the cheek + temple
    for (const [x, y] of [[26, 19], [27, 19], [27, 20], [27, 21], [26, 22], [25, 22], [24, 22]]) put(x, y, GLOW);
    put(24, 22, WHITE); rect(26, 11, 3, 1, GLOW); put(28, 12, WHITE);
  }

  // ----- 9. compose: outline the character, put it on its background -----
  const outlined = outlineGrid(g);
  const bg = BG[a.bg];
  const cv = document.createElement('canvas');
  cv.width = N; cv.height = N;
  const ctx = cv.getContext('2d');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, N, N);
  // faint scan-lines and a corner glow so the portrait feels like a screen
  ctx.fillStyle = lit(bg, 0.12);
  for (let y = 0; y < N; y += 4) ctx.fillRect(0, y, N, 1);
  ctx.fillStyle = lit(bg, 0.25); ctx.fillRect(0, 0, 3, 1); ctx.fillRect(0, 0, 1, 3);
  for (let y = 0; y < N; y++) for (let x = 0; x < N; x++) if (outlined[y][x]) { ctx.fillStyle = outlined[y][x]; ctx.fillRect(x, y, 1, 1); }
  return cv;
}
